//! Safe Rust bindings for kylin-coreai-speech SDK.
//!
//! Uses [`libloading`] to load `libkysdk-coreai-speech.so` at runtime.
//! Type definitions are generated by bindgen.
//!
//! # Library search order
//!
//! 1. `KART_SPEECH_SDK_PATH` environment variable (full path to .so)
//! 2. System library path (`/usr/lib/x86_64-linux-gnu/...`)
//! 3. `./libkysdk-coreai-speech.so` (next to the binary)
//! 4. Bare SONAME (交由动态链接器 / `LD_LIBRARY_PATH` 解析)
//!
//! # Safety
//!
//! This crate is the **only** place where `unsafe` is permitted for this SDK.
//! All `unsafe` is confined to `extern "C"` call sites.
//! The public API is fully safe Rust.

use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_void};
use std::path::PathBuf;
use std::sync::{Arc, OnceLock};

use libloading::{Library, Symbol};
use thiserror::Error;
use tokio::sync::mpsc;

// Re-export types from bindgen
#[cfg(not(feature = "stub"))]
#[allow(nonstandard_style, unused)]
mod bindings;

#[cfg(not(feature = "stub"))]
pub use bindings::{
    AudioConfig, ModelDeployType, SpeechModelConfig, SpeechRecognitionResult,
    SpeechRecognitionResultCallback, SpeechRecognitionSession,
    SpeechSynthesisResult, SpeechSynthesisResultCallback, SpeechSynthesizerSession,
};

// Stub types when feature = "stub" (for compilation without SDK headers)
#[cfg(feature = "stub")]
pub mod stub_types {
    use std::os::raw::c_void;

    // Type aliases matching what bindgen generates (function pointer types)
    pub type ModelDeployType = u32;
    pub type AudioConfig = *mut std::ffi::c_void;
    pub type SpeechModelConfig = *mut std::ffi::c_void;
    pub type SpeechSynthesisResult = *mut std::ffi::c_void;
    pub type SpeechRecognitionResult = *mut std::ffi::c_void;
    pub type SpeechSynthesisResultCallback =
        Option<unsafe extern "C" fn(*mut SpeechSynthesisResult, *mut c_void)>;
    pub type SpeechRecognitionResultCallback =
        Option<unsafe extern "C" fn(*mut SpeechRecognitionResult, *mut c_void)>;
    pub type SpeechSynthesizerSession = *mut std::ffi::c_void;
    pub type SpeechRecognitionSession = *mut std::ffi::c_void;
}

#[cfg(feature = "stub")]
pub use stub_types::{
    AudioConfig, ModelDeployType, SpeechModelConfig, SpeechRecognitionResult,
    SpeechRecognitionResultCallback, SpeechRecognitionSession, SpeechSynthesisResult,
    SpeechSynthesisResultCallback, SpeechSynthesizerSession,
};

// ── Error Types ─────────────────────────────────────────────────────────────

/// Errors returned by kylin-speech operations.
#[derive(Debug, Error)]
pub enum KylinSpeechError {
    /// SDK library not found or failed to load.
    #[error("kylin-coreai-speech SDK not found — set KART_SPEECH_SDK_PATH or install the SDK")]
    LibraryNotFound,

    /// Session creation failed.
    #[error("Session creation failed")]
    SessionCreateFailed,

    /// Session initialization failed.
    #[error("Session initialization failed (code {0})")]
    InitFailed(i32),

    /// Invalid input (e.g., null bytes in string).
    #[error("Invalid input: {0}")]
    InvalidInput(String),

    /// SDK returned an error code.
    #[error("SDK error (code {0}): {1}")]
    SdkError(i32, String),

    /// Callback wait timed out.
    #[error("Callback wait timed out")]
    Timeout,

    /// Function not found in library.
    #[error("Function not found in library: {0}")]
    FunctionNotFound(String),
}

pub type Result<T> = std::result::Result<T, KylinSpeechError>;

// ── Synthesis Output ─────────────────────────────────────────────────────────

/// Output from a speech synthesis operation.
#[derive(Debug, Clone)]
pub struct SynthesisOutput {
    /// Raw audio data (PCM format).
    pub audio_data: Vec<u8>,
    /// Sample rate in Hz (e.g., 16000, 24000).
    pub sample_rate: u32,
    /// Number of audio channels (1 = mono).
    pub channels: u16,
    /// Audio format descriptor.
    pub format: String,
}

// ── Callback Context ─────────────────────────────────────────────────────────

/// Context passed to the C callback for TTS synthesis results.
struct SynthesisCallbackContext {
    /// TX channel for synthesis chunks to async world.
    tx: mpsc::UnboundedSender<SynthesisChunk>,
}

/// A chunk of audio data from the TTS SDK.
#[derive(Debug, Clone)]
pub struct SynthesisChunk {
    /// Audio data for this chunk (may be empty for non-audio events).
    pub audio_data: Vec<u8>,
    /// Whether synthesis is complete.
    pub is_final: bool,
    /// Reason code (0 = success).
    pub reason: i32,
    /// Human-readable error message (if reason != 0).
    pub error_message: Option<String>,
}

/// Context passed to the C callback for STT recognition results.
struct RecognitionCallbackContext {
    /// TX channel for recognition results to async world.
    tx: mpsc::UnboundedSender<RecognitionResult>,
}

/// Result from speech recognition.
#[derive(Debug, Clone)]
pub struct RecognitionResult {
    /// Recognized text (empty on error).
    pub text: String,
    /// Whether recognition is complete.
    pub is_final: bool,
    /// Reason code (0 = success).
    pub reason: i32,
    /// Human-readable error message (if reason != 0).
    pub error_message: Option<String>,
}

// ── Library Loading ──────────────────────────────────────────────────────────

static KART_SPEECH_LIB: OnceLock<Option<Library>> = OnceLock::new();

fn lib() -> Option<&'static Library> {
    KART_SPEECH_LIB
        .get_or_init(|| {
            #[cfg(target_arch = "x86_64")]
            const SYSTEM_LIB: &str = "/usr/lib/x86_64-linux-gnu/libkysdk-coreai-speech.so";
            #[cfg(target_arch = "aarch64")]
            const SYSTEM_LIB: &str = "/usr/lib/aarch64-linux-gnu/libkysdk-coreai-speech.so";
            #[cfg(not(any(target_arch = "x86_64", target_arch = "aarch64")))]
            const SYSTEM_LIB: &str = "";

            let candidates: Vec<PathBuf> = vec![
                // 1. Explicit env-var override (full path)
                std::env::var("KART_SPEECH_SDK_PATH")
                    .ok()
                    .map(PathBuf::from)
                    .unwrap_or_default(),
                // 2. System library — multiarch path for this build target
                PathBuf::from(SYSTEM_LIB),
                // 3. Next to the running binary (deployment)
                std::env::current_exe()
                    .ok()
                    .and_then(|e| e.parent().map(|d| d.join("libkysdk-coreai-speech.so")))
                    .unwrap_or_default(),
                // 4. Bare SONAME — defers to the dynamic linker
                PathBuf::from("libkysdk-coreai-speech.so"),
            ];

            for path in &candidates {
                if path.as_os_str().is_empty() {
                    continue;
                }
                match unsafe { Library::new(path) } {
                    Ok(lib) => {
                        // Verify library exports expected STT symbols
                        let valid = unsafe {
                            lib.get::<unsafe extern "C" fn() -> *mut SpeechRecognitionSession>(
                                b"speech_recognizer_create_session\0",
                            )
                            .is_ok()
                        };
                        if valid {
                            eprintln!("[kart-speech-sys] loaded library from {}", path.display());
                            return Some(lib);
                        } else {
                            eprintln!(
                                "[kart-speech-sys] {} loaded but STT symbols not found — not a valid SDK",
                                path.display()
                            );
                        }
                    }
                    Err(e) => {
                        eprintln!("[kart-speech-sys] could not load {}: {}", path.display(), e);
                    }
                }
            }
            eprintln!(
                "[kart-speech-sys] no library found; set KART_SPEECH_SDK_PATH or install the SDK"
            );
            None
        })
        .as_ref()
}

// ── C Callback Bridge (TTS) ─────────────────────────────────────────────────

/// C-compatible callback wrapper for TTS results.
///
/// # Safety
/// This function is called from C code. The user_data must be a valid
/// pointer to a SynthesisCallbackContext.
unsafe extern "C" fn synthesis_result_callback(
    result: *mut SpeechSynthesisResult,
    user_data: *mut c_void,
) {
    if user_data.is_null() {
        return;
    }

    let ctx = unsafe { &*(user_data as *const SynthesisCallbackContext) };

    if let Some(lib) = lib() {
        // Get reason
        let get_reason: Symbol<unsafe extern "C" fn(*mut SpeechSynthesisResult) -> i32> =
            unsafe {
                match lib.get(b"speech_synthesis_result_get_reason\0") {
                    Ok(f) => f,
                    Err(_) => return,
                }
            };

        // Get audio data — use bindings signature (data_length: *mut u32)
        let get_data: Symbol<
            unsafe extern "C" fn(*mut SpeechSynthesisResult, *mut u32) -> *const u8,
        > = unsafe {
            match lib.get(b"speech_synthesis_result_get_data\0") {
                Ok(f) => f,
                Err(_) => {
                    eprintln!("[KartTTS CB] speech_synthesis_result_get_data not found");
                    return;
                }
            }
        };

        // Get error message
        let get_error_msg: Symbol<
            unsafe extern "C" fn(*mut SpeechSynthesisResult) -> *const c_char,
        > = unsafe {
            match lib.get(b"speech_synthesis_result_get_error_message\0") {
                Ok(f) => f,
                Err(_) => return,
            }
        };

        let reason = unsafe { get_reason(result) };
        let is_final = reason == 8; // SPEECH_SYNTHESIS_COMPLETED

        let audio_data = if !result.is_null() {
            let mut data_length: u32 = 0;
            let ptr = unsafe { get_data(result, &mut data_length) };
            let len = data_length as usize;
            if !ptr.is_null() && len > 0 {
                unsafe { std::slice::from_raw_parts(ptr, len).to_vec() }
            } else {
                Vec::new()
            }
        } else {
            Vec::new()
        };

        let error_message = unsafe {
            let ptr = get_error_msg(result);
            if !ptr.is_null() {
                let msg = CStr::from_ptr(ptr).to_str().ok().map(String::from).unwrap_or_default();
                if reason == 1 && !msg.is_empty() {
                    Some(msg)
                } else {
                    None
                }
            } else {
                None
            }
        };

        let chunk = SynthesisChunk {
            audio_data,
            is_final,
            reason,
            error_message,
        };

        let _ = ctx.tx.send(chunk);
    }
}

// ── C Callback Bridge (STT) ─────────────────────────────────────────────────

/// C-compatible callback wrapper for STT results.
///
/// # Safety
/// This function is called from C code. The user_data must be a valid
/// pointer to a RecognitionCallbackContext.
unsafe extern "C" fn recognition_result_callback(
    result: *mut SpeechRecognitionResult,
    user_data: *mut c_void,
) {
    if user_data.is_null() {
        return;
    }

    let ctx = unsafe { &*(user_data as *const RecognitionCallbackContext) };

    if let Some(lib) = lib() {
        // Get reason
        let get_reason: Symbol<unsafe extern "C" fn(*mut SpeechRecognitionResult) -> i32> =
            unsafe {
                match lib.get(b"speech_recognition_result_get_reason\0") {
                    Ok(f) => f,
                    Err(_) => return,
                }
            };

        // Get text
        let get_text: Symbol<
            unsafe extern "C" fn(*mut SpeechRecognitionResult) -> *const c_char,
        > = unsafe {
            match lib.get(b"speech_recognition_result_get_text\0") {
                Ok(f) => f,
                Err(_) => return,
            }
        };

        // Get error message
        let get_error_msg: Symbol<
            unsafe extern "C" fn(*mut SpeechRecognitionResult) -> *const c_char,
        > = unsafe {
            match lib.get(b"speech_recognition_result_get_error_message\0") {
                Ok(f) => f,
                Err(_) => return,
            }
        };

        let reason = unsafe { get_reason(result) };
        let is_final = reason == 4; // SPEECH_RECOGNIZED

        let text = unsafe {
            let ptr = get_text(result);
            if !ptr.is_null() {
                CStr::from_ptr(ptr).to_str().ok().map(String::from).unwrap_or_default()
            } else {
                String::new()
            }
        };

        let error_message = unsafe {
            let ptr = get_error_msg(result);
            if !ptr.is_null() {
                let msg = CStr::from_ptr(ptr).to_str().ok().map(String::from).unwrap_or_default();
                // Only set error_message if reason indicates an actual error (reason == 1)
                // Note: reason == 4 (SPEECH_RECOGNIZED) is a successful result, not an error
                if reason == 1 && !msg.is_empty() {
                    Some(msg)
                } else {
                    None
                }
            } else {
                None
            }
        };

        let result_data = RecognitionResult {
            text,
            is_final,
            reason,
            error_message,
        };

        let _ = ctx.tx.send(result_data);
    }
}

// ── Session Handle (RAII) ────────────────────────────────────────────────────

/// Safe RAII handle over the TTS session.
///
/// Automatically destroys the session on `Drop`.
pub struct KylinSpeechSynthesizer {
    session: *mut SpeechSynthesizerSession,
    /// Rust-side Arc that owns the callback context allocation.
    callback_ctx: Option<Arc<SynthesisCallbackContext>>,
    /// Raw pointer derived from a cloned Arc and passed to C.
    callback_raw: *const SynthesisCallbackContext,
}

impl KylinSpeechSynthesizer {
    /// Create a new TTS synthesizer with the given model and deploy type.
    pub fn new(model_name: &str, deploy_type: &str) -> Result<Self> {
        let lib = lib().ok_or(KylinSpeechError::LibraryNotFound)?;

        // Create session
        let session: *mut SpeechSynthesizerSession = unsafe {
            let f: Symbol<unsafe extern "C" fn() -> *mut SpeechSynthesizerSession> = lib
                .get(b"speech_synthesizer_create_session\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            f()
        };

        if session.is_null() {
            return Err(KylinSpeechError::SessionCreateFailed);
        }

        // Initialize session
        let ret: i32 = unsafe {
            let f: Symbol<unsafe extern "C" fn(*mut SpeechSynthesizerSession) -> i32> = lib
                .get(b"speech_synthesizer_init_session\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            f(session)
        };

        if ret != 0 {
            unsafe {
                let destroy: Symbol<unsafe extern "C" fn(*mut *mut SpeechSynthesizerSession)> =
                    lib.get(b"speech_synthesizer_destroy_session\0")
                        .map_err(|_| KylinSpeechError::LibraryNotFound)?;
                let mut s = session;
                destroy(&mut s);
            }
            return Err(KylinSpeechError::InitFailed(ret));
        }

        // Set model config
        let deploy_type_val = match deploy_type {
            "public_cloud" => 1u32,
            "private_cloud" => 2u32,
            _ => 0u32, // on_device
        };

        unsafe {
            // Create model config
            let create_config: Symbol<unsafe extern "C" fn() -> *mut SpeechModelConfig> =
                lib.get(b"speech_model_config_create\0")
                    .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            let config = create_config();

            if config.is_null() {
                return Err(KylinSpeechError::InitFailed(-1));
            }

            // Set model name
            let model_cstr = CString::new(model_name)
                .map_err(|e| KylinSpeechError::InvalidInput(e.to_string()))?;
            let set_name: Symbol<
                unsafe extern "C" fn(*mut SpeechModelConfig, *const c_char),
            > = lib
                .get(b"speech_model_config_set_name\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            set_name(config, model_cstr.as_ptr());

            // Set deploy type (void function — no return value to check)
            let set_deploy_type: Symbol<
                unsafe extern "C" fn(*mut SpeechModelConfig, ModelDeployType),
            > = lib
                .get(b"speech_model_config_set_deploy_type\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            set_deploy_type(config, deploy_type_val as ModelDeployType);

            // Apply config to session (void function)
            let set_config: Symbol<
                unsafe extern "C" fn(*mut SpeechSynthesizerSession, *mut SpeechModelConfig),
            > = lib
                .get(b"speech_synthesizer_set_model_config\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            set_config(session, config);

            // Destroy config
            let destroy_config: Symbol<unsafe extern "C" fn(*mut *mut SpeechModelConfig)> =
                lib.get(b"speech_model_config_destroy\0")
                    .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            let mut config_ptr = config;
            destroy_config(&mut config_ptr);

            // Create audio config for PCM output
            let create_audio_config: Symbol<unsafe extern "C" fn() -> *mut AudioConfig> =
                lib.get(b"audio_config_create_audio_output_from_pcm_data\0")
                    .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            let audio_config = create_audio_config();

            if !audio_config.is_null() {
                // PCM output format is set automatically by audio_config_create_audio_output_from_pcm_data

                // Apply audio config (void function)
                let set_audio_config: Symbol<
                    unsafe extern "C" fn(*mut SpeechSynthesizerSession, *mut AudioConfig),
                > = lib
                    .get(b"speech_synthesizer_set_audio_config\0")
                    .map_err(|_| KylinSpeechError::LibraryNotFound)?;
                set_audio_config(session, audio_config);

                // Destroy audio config (void function — session retains a copy internally)
                let destroy_audio_config: Symbol<unsafe extern "C" fn(*mut *mut AudioConfig)> =
                    lib.get(b"audio_config_destroy\0")
                        .map_err(|_| KylinSpeechError::LibraryNotFound)?;
                let mut audio_config_ptr = audio_config;
                destroy_audio_config(&mut audio_config_ptr);
            }
        }

        tracing::debug!("KylinSpeechSynthesizer created successfully");

        Ok(Self {
            session,
            callback_ctx: None,
            callback_raw: std::ptr::null(),
        })
    }

    /// Synthesize text and return audio data.
    pub async fn synthesize(&mut self, text: &str) -> Result<SynthesisOutput> {
        let lib = lib().ok_or(KylinSpeechError::LibraryNotFound)?;

        let (tx, mut rx) = mpsc::unbounded_channel();

        // Build Arc for the context, give C a raw pointer from a clone
        let ctx = Arc::new(SynthesisCallbackContext { tx });
        let raw = Arc::into_raw(Arc::clone(&ctx));

        // Reclaim any previous raw ptr we gave to C
        if !self.callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.callback_raw)) }
        }

        // Register callback (void function)
        unsafe {
            let set_callback: Symbol<
                unsafe extern "C" fn(
                    *mut SpeechSynthesizerSession,
                    SpeechSynthesisResultCallback,
                    *mut c_void,
                ),
            > = lib
                .get(b"speech_synthesizer_result_set_callback\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            set_callback(
                self.session,
                Some(synthesis_result_callback),
                raw as *mut c_void,
            );
        }

        // Enable internal event loop (void function)
        unsafe {
            let enable_loop: Symbol<unsafe extern "C" fn(*mut SpeechSynthesizerSession, bool)> =
                lib.get(b"speech_synthesizer_enable_internal_event_loop\0")
                    .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            enable_loop(self.session, true);
        }

        // Start synthesis (void function — async, results via callback)
        let text_cstr =
            CString::new(text).map_err(|e| KylinSpeechError::InvalidInput(e.to_string()))?;
        let text_len = text.len() as u32;

        unsafe {
            let synthesize: Symbol<
                unsafe extern "C" fn(*mut SpeechSynthesizerSession, *const c_char, u32),
            > = lib
                .get(b"speech_synthesizer_synthesize_text_async\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            synthesize(self.session, text_cstr.as_ptr(), text_len);
        }

        // Store context but note: the SDK may fire callbacks until session is destroyed.
        // We avoid reclaiming the Arc in Drop to prevent use-after-free.
        self.callback_ctx = Some(ctx);
        self.callback_raw = raw;

        // Collect audio chunks until completion
        let mut audio_data = Vec::new();
        let sample_rate = 16000u32;
        let channels = 1u16;
        let mut is_final = false;
        let mut error_message: Option<String> = None;

        while !is_final {
            match tokio::time::timeout(std::time::Duration::from_secs(30), rx.recv()).await {
                Ok(Some(chunk)) => {
                    if chunk.reason != 0 && chunk.error_message.is_some() {
                        error_message = chunk.error_message.clone();
                    }
                    audio_data.extend_from_slice(&chunk.audio_data);
                    is_final = chunk.is_final;
                }
                Ok(None) => {
                    return Err(KylinSpeechError::Timeout);
                }
                Err(_) => {
                    return Err(KylinSpeechError::Timeout);
                }
            }
        }

        if let Some(msg) = error_message {
            return Err(KylinSpeechError::SdkError(-1, msg));
        }

        Ok(SynthesisOutput {
            audio_data,
            sample_rate,
            channels,
            format: "pcm".to_string(),
        })
    }
}

impl Drop for KylinSpeechSynthesizer {
    fn drop(&mut self) {
        if let Some(lib) = lib() {
            unsafe {
                // Disable event loop first, then destroy session
                if let Ok(disable_loop) =
                    lib.get::<unsafe extern "C" fn(*mut SpeechSynthesizerSession, bool)>(
                        b"speech_synthesizer_enable_internal_event_loop\0",
                    )
                {
                    disable_loop(self.session, false);
                }
                if let Ok(f) =
                    lib.get::<unsafe extern "C" fn(*mut *mut SpeechSynthesizerSession)>(
                        b"speech_synthesizer_destroy_session\0",
                    )
                {
                    f(&mut self.session);
                }
            }
        }
        // Reclaim the Arc refcount we gave to C
        if !self.callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.callback_raw)) };
            self.callback_raw = std::ptr::null();
        }
    }
}

unsafe impl Send for KylinSpeechSynthesizer {}
unsafe impl Sync for KylinSpeechSynthesizer {}

// ── Speech Recognizer ────────────────────────────────────────────────────────

/// Safe RAII handle over the STT session.
///
/// Automatically destroys the session on `Drop`.
pub struct KylinSpeechRecognizer {
    session: *mut SpeechRecognitionSession,
    /// Rust-side Arc that owns the callback context allocation.
    callback_ctx: Option<Arc<RecognitionCallbackContext>>,
    /// Raw pointer derived from a cloned Arc and passed to C.
    callback_raw: *const RecognitionCallbackContext,
}

impl KylinSpeechRecognizer {
    /// Create a new STT recognizer with the given model and deploy type.
    pub fn new(model_name: &str, deploy_type: &str) -> Result<Self> {
        let lib = lib().ok_or(KylinSpeechError::LibraryNotFound)?;

        // Create session
        let session: *mut SpeechRecognitionSession = unsafe {
            let f: Symbol<unsafe extern "C" fn() -> *mut SpeechRecognitionSession> = lib
                .get(b"speech_recognizer_create_session\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            f()
        };

        if session.is_null() {
            return Err(KylinSpeechError::SessionCreateFailed);
        }

        // Initialize session
        let ret: i32 = unsafe {
            let f: Symbol<unsafe extern "C" fn(*mut SpeechRecognitionSession) -> i32> = lib
                .get(b"speech_recognizer_init_session\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            f(session)
        };

        if ret != 0 {
            unsafe {
                let destroy: Symbol<unsafe extern "C" fn(*mut *mut SpeechRecognitionSession)> =
                    lib.get(b"speech_recognizer_destroy_session\0")
                        .map_err(|_| KylinSpeechError::LibraryNotFound)?;
                let mut s = session;
                destroy(&mut s);
            }
            return Err(KylinSpeechError::InitFailed(ret));
        }

        // Set model config
        let deploy_type_val = match deploy_type {
            "public_cloud" => 1u32,
            "private_cloud" => 2u32,
            _ => 0u32, // on_device
        };

        unsafe {
            // Create model config
            let create_config: Symbol<unsafe extern "C" fn() -> *mut SpeechModelConfig> =
                lib.get(b"speech_model_config_create\0")
                    .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            let config = create_config();

            if config.is_null() {
                return Err(KylinSpeechError::InitFailed(-1));
            }

            // Set model name (void function)
            let model_cstr = CString::new(model_name)
                .map_err(|e| KylinSpeechError::InvalidInput(e.to_string()))?;
            let set_name: Symbol<
                unsafe extern "C" fn(*mut SpeechModelConfig, *const c_char),
            > = lib
                .get(b"speech_model_config_set_name\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            set_name(config, model_cstr.as_ptr());

            // Set deploy type (void function)
            let set_deploy_type: Symbol<
                unsafe extern "C" fn(*mut SpeechModelConfig, ModelDeployType),
            > = lib
                .get(b"speech_model_config_set_deploy_type\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            set_deploy_type(config, deploy_type_val as ModelDeployType);

            // Apply config to session (void function)
            let set_config: Symbol<
                unsafe extern "C" fn(*mut SpeechRecognitionSession, *mut SpeechModelConfig),
            > = lib
                .get(b"speech_recognizer_set_model_config\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            set_config(session, config);

            // Destroy config (void function)
            let destroy_config: Symbol<unsafe extern "C" fn(*mut *mut SpeechModelConfig)> =
                lib.get(b"speech_model_config_destroy\0")
                    .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            let mut config_ptr = config;
            destroy_config(&mut config_ptr);
        }

        tracing::debug!("KylinSpeechRecognizer created successfully");

        Ok(Self {
            session,
            callback_ctx: None,
            callback_raw: std::ptr::null(),
        })
    }

    /// Recognize speech from PCM audio data.
    pub async fn recognize(&mut self, pcm_data: &[u8], _sample_rate: u32) -> Result<String> {
        let lib = lib().ok_or(KylinSpeechError::LibraryNotFound)?;

        if pcm_data.is_empty() {
            return Err(KylinSpeechError::InvalidInput("empty audio data".to_string()));
        }

        let (tx, mut rx) = mpsc::unbounded_channel();

        // Build Arc for context, give C a raw pointer from a clone
        let ctx = Arc::new(RecognitionCallbackContext { tx });
        let raw = Arc::into_raw(Arc::clone(&ctx));

        // Reclaim any previous raw ptr
        if !self.callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.callback_raw)) }
        }

        // Register callback (void function)
        unsafe {
            let set_callback: Symbol<
                unsafe extern "C" fn(
                    *mut SpeechRecognitionSession,
                    SpeechRecognitionResultCallback,
                    *mut c_void,
                ),
            > = lib
                .get(b"speech_recognizer_result_set_callback\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            set_callback(
                self.session,
                Some(recognition_result_callback),
                raw as *mut c_void,
            );
        }

        // Enable internal event loop (void function)
        unsafe {
            let enable_loop: Symbol<unsafe extern "C" fn(*mut SpeechRecognitionSession, bool)> =
                lib.get(b"speech_recognizer_enable_internal_event_loop\0")
                    .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            enable_loop(self.session, true);
        }

        // Create audio config with PCM data
        unsafe {
            let create_audio_config: Symbol<
                unsafe extern "C" fn(*const u8, u32) -> *mut AudioConfig,
            > = lib
                .get(b"audio_config_create_once_audio_input_from_pcm_data\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            let audio_config =
                create_audio_config(pcm_data.as_ptr(), pcm_data.len() as u32);

            if !audio_config.is_null() {
                // Apply audio config (void function)
                // NOTE: Do NOT call audio_config_set_input_audio_rate here —
                // the PCM config already has the correct sample rate from the data.
                let set_audio_config: Symbol<
                    unsafe extern "C" fn(*mut SpeechRecognitionSession, *mut AudioConfig),
                > = lib
                    .get(b"speech_recognizer_set_audio_config\0")
                    .map_err(|_| KylinSpeechError::LibraryNotFound)?;
                set_audio_config(self.session, audio_config);

                // NOTE: Do NOT destroy audio config here — the session makes an internal copy
                // and calling destroy may cause use-after-free when session is destroyed.
                // The SDK manages the lifetime of the copied config internally.
            }
        }

        // Start recognition (void function — async, results via callback)
        unsafe {
            let recognize: Symbol<unsafe extern "C" fn(*mut SpeechRecognitionSession)> = lib
                .get(b"speech_recognizer_recognize_once_async\0")
                .map_err(|_| KylinSpeechError::LibraryNotFound)?;
            recognize(self.session);
        }

        self.callback_ctx = Some(ctx);
        self.callback_raw = raw;

        // Wait for recognition result
        let mut result_text = String::new();
        let mut is_final = false;
        let mut error_message: Option<String> = None;

        while !is_final {
            match tokio::time::timeout(std::time::Duration::from_secs(30), rx.recv()).await {
                Ok(Some(result)) => {
                    if result.reason != 0 && result.error_message.is_some() {
                        error_message = result.error_message.clone();
                    }
                    result_text = result.text;
                    is_final = result.is_final;
                }
                Ok(None) => {
                    return Err(KylinSpeechError::Timeout);
                }
                Err(_) => {
                    return Err(KylinSpeechError::Timeout);
                }
            }
        }

        if let Some(msg) = error_message {
            return Err(KylinSpeechError::SdkError(-1, msg));
        }

        Ok(result_text)
    }
}

impl Drop for KylinSpeechRecognizer {
    fn drop(&mut self) {
        // Disable internal event loop before destroying session
        if let Some(lib) = lib() {
            unsafe {
                if let Ok(disable_loop) =
                    lib.get::<unsafe extern "C" fn(*mut SpeechRecognitionSession, bool)>(
                        b"speech_recognizer_enable_internal_event_loop\0",
                    )
                {
                    disable_loop(self.session, false);
                }
                if let Ok(f) =
                    lib.get::<unsafe extern "C" fn(*mut *mut SpeechRecognitionSession)>(
                        b"speech_recognizer_destroy_session\0",
                    )
                {
                    f(&mut self.session);
                }
            }
        }
        // Reclaim the Arc refcount we gave to C
        if !self.callback_raw.is_null() {
            unsafe { drop(Arc::from_raw(self.callback_raw)) };
            self.callback_raw = std::ptr::null();
        }
    }
}

unsafe impl Send for KylinSpeechRecognizer {}
unsafe impl Sync for KylinSpeechRecognizer {}

/// Check if the SDK library is available.
pub fn is_available() -> bool {
    lib().is_some()
}

// ── Tests ────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn is_available_does_not_panic() {
        let _ = is_available();
    }

    #[test]
    fn error_display() {
        let err = KylinSpeechError::LibraryNotFound;
        assert!(err.to_string().contains("not found"));

        let err = KylinSpeechError::InitFailed(-1);
        assert!(err.to_string().contains("-1"));

        let err = KylinSpeechError::InvalidInput("null byte".into());
        assert!(err.to_string().contains("Invalid input"));
        assert!(err.to_string().contains("null byte"));
    }

    #[test]
    fn error_sdk_error() {
        let err = KylinSpeechError::SdkError(1001, "service unavailable".into());
        assert!(err.to_string().contains("SDK error"));
        assert!(err.to_string().contains("1001"));
        assert!(err.to_string().contains("service unavailable"));
    }

    #[test]
    fn error_function_not_found() {
        let err = KylinSpeechError::FunctionNotFound("speech_synthesizer_foo".into());
        assert!(err.to_string().contains("Function not found"));
        assert!(err.to_string().contains("speech_synthesizer_foo"));
    }

    #[test]
    fn error_timeout() {
        let err = KylinSpeechError::Timeout;
        assert!(err.to_string().contains("timed out"));
    }

    #[test]
    fn recognizer_new_returns_error_or_success() {
        let result = KylinSpeechRecognizer::new("test_model", "on_device");
        match &result {
            Ok(_) => tracing::debug!("KylinSpeechRecognizer created OK"),
            Err(e) => tracing::debug!("KylinSpeechRecognizer returned error: {}", e),
        }
        let _ = result;
    }

    #[test]
    fn lib_loads_on_first_call() {
        let lib_opt = lib();
        match lib_opt {
            Some(lib) => {
                let has_sym = unsafe {
                    lib.get::<unsafe extern "C" fn() -> *mut SpeechRecognitionSession>(
                        b"speech_recognizer_create_session\0",
                    )
                    .is_ok()
                };
                assert!(has_sym, "Library loaded but STT symbol not found");
            }
            None => {
                tracing::debug!("lib() returned None — SDK not available");
            }
        }
    }

    #[test]
    fn synthesizer_new_returns_error_or_success() {
        let result = KylinSpeechSynthesizer::new("test_model", "on_device");
        match &result {
            Ok(_) => tracing::debug!("KylinSpeechSynthesizer created OK"),
            Err(e) => tracing::debug!("KylinSpeechSynthesizer returned error: {}", e),
        }
        let _ = result;
    }
}
